// Curriculum copy lives outside product screens so it can evolve independently.
export type LearningTrack = "Java" | "Spring Boot";
export type LearningMission = {
  id: number; phase: string; rank: string; title: string; objective: string; duration: string; xp: number;
  lesson: { why: string; explanation: string; keyPoints: string[]; whenToUse: string[]; code: string; notes: string[] };
  quest: { brief: string; requirements: string[]; starter: string; hint: string; expected: string };
  quiz: { question: string; options: string[]; answer: number; explanation: string };
};

export const javaMissions: LearningMission[] = [
  { id:0, phase:"Foundation Gate", rank:"E", title:"How Java becomes a running program", objective:"Build a correct mental model of source code, bytecode, the JVM, variables and program flow.", duration:"35 min", xp:180,
    lesson:{ why:"Developers who understand the runtime diagnose errors faster and stop treating compiler messages as magic.", explanation:"The JDK gives you development tools such as javac. javac compiles .java source into platform-neutral bytecode. The JVM loads, verifies and executes that bytecode. The JRE is the runtime portion needed to execute Java programs. A Java application starts at main; each variable has a declared type and a scope that limits where it can be used.", keyPoints:["JDK = tools + runtime; JVM executes bytecode","Compilation catches type and syntax problems before execution","Primitive values store data directly; reference variables point to objects","Prefer the narrowest useful scope and descriptive names"], whenToUse:["Explaining why Java runs across operating systems","Separating compile-time failures from runtime failures","Choosing primitive or object representations"], code:`public class OrderTotal {\n  public static void main(String[] args) {\n    int quantity = 3;\n    double unitPrice = 249.50;\n    double total = quantity * unitPrice;\n    System.out.printf("Total: %.2f%n", total);\n  }\n}` , notes:["Money should later use BigDecimal; double is used here only to teach numeric flow","Never use uninitialized local variables","Class names use PascalCase; variables and methods use camelCase"]},
    quest:{ brief:"Create a command-line bill calculator that receives quantity and unit price, rejects invalid values and prints subtotal plus 18% tax.", requirements:["Use Scanner for input","Reject quantity <= 0 and price < 0","Keep tax rate in a final constant","Print values to two decimal places"], starter:`Scanner scanner = new Scanner(System.in);\n// Read values, validate, calculate and print`, hint:"Validate immediately after reading. Return from main when input is invalid.", expected:"For quantity 2 and price 100: subtotal 200.00, tax 36.00, total 236.00."},
    quiz:{ question:"Which component executes compiled Java bytecode?", options:["javac","JVM","Source editor","Maven"], answer:1, explanation:"javac produces bytecode; the JVM loads and executes it."}},
  { id:1, phase:"Foundation Gate", rank:"E", title:"Decisions, loops and defensive input", objective:"Control program flow without creating tangled or infinite logic.", duration:"40 min", xp:220,
    lesson:{ why:"Real applications are rules expressed as decisions. Poor branching produces duplicated logic and missed edge cases.", explanation:"Use if/else for ranges and compound business conditions, switch for a closed set of discrete values, and loops for repetition. A loop needs a clear initialization, continuation condition and progress step. Guard clauses handle invalid states early so the main path stays readable.", keyPoints:["Put exceptional paths first with guard clauses","Use switch expressions for fixed choices","Use for when the iteration count is known; while when a condition controls repetition","Avoid deeply nested branches; extract named methods"], whenToUse:["Eligibility and validation rules","Menu-driven console applications","Batching through collections or retrying bounded work"], code:`static String riskBand(int score) {\n  if (score < 0 || score > 100) {\n    throw new IllegalArgumentException("score must be 0..100");\n  }\n  if (score >= 80) return "LOW";\n  if (score >= 50) return "MEDIUM";\n  return "HIGH";\n}` , notes:["Conditions should read like business language","Never use an unbounded retry loop","Throwing is appropriate when the caller violated a method contract"]},
    quest:{ brief:"Build an ATM withdrawal validator with balance, amount, daily limit and note-denomination rules.", requirements:["Reject non-positive amounts","Reject amounts not divisible by 100","Reject insufficient balance and daily-limit breach","Return one clear message per failure and APPROVED otherwise"], starter:`static String validateWithdrawal(int balance, int withdrawnToday, int amount) {\n  // implement guard clauses\n}`, hint:"Order validations from cheapest/basic to business-dependent checks.", expected:"balance=5000, withdrawnToday=1000, amount=2000 returns APPROVED."},
    quiz:{ question:"Why are guard clauses generally preferable to deeply nested if blocks?", options:["They execute faster in every case","They keep invalid paths separate and reduce nesting","They avoid all exceptions","They replace tests"], answer:1, explanation:"Their main benefit is readability and a clearer happy path, not guaranteed speed."}},
  { id:2, phase:"Object Builder Gate", rank:"D", title:"Model behavior with classes and encapsulation", objective:"Design objects that protect their own valid state instead of acting as data bags.", duration:"50 min", xp:300,
    lesson:{ why:"Enterprise code changes constantly. Encapsulation localizes rules so invalid data cannot leak through the system.", explanation:"A class combines state and behavior. Keep fields private, establish invariants in constructors, and expose intention-revealing methods rather than setters for everything. Composition models has-a relationships and is usually safer than inheritance. Records suit immutable data carriers; classes suit entities with behavior and lifecycle.", keyPoints:["Constructors should produce valid objects","Tell an object what to do; do not pull out state and manipulate it elsewhere","Prefer composition over inheritance unless the subtype truly satisfies is-a","Use equals/hashCode consistently for value objects"], whenToUse:["Domain entities such as Account or Order","Reusable value objects such as Money or EmailAddress","Separating domain rules from user-interface code"], code:`public final class BankAccount {\n  private final String number;\n  private BigDecimal balance;\n\n  public BankAccount(String number, BigDecimal opening) {\n    if (opening.signum() < 0) throw new IllegalArgumentException();\n    this.number = Objects.requireNonNull(number);\n    this.balance = opening;\n  }\n  public void withdraw(BigDecimal amount) {\n    if (amount.signum() <= 0 || balance.compareTo(amount) < 0)\n      throw new IllegalArgumentException("Invalid withdrawal");\n    balance = balance.subtract(amount);\n  }\n}` , notes:["Do not expose mutable fields directly","Avoid anemic models made only of getters and setters","Use BigDecimal for exact decimal money calculations"]},
    quest:{ brief:"Model a LibraryBook that can be borrowed and returned while preserving valid state.", requirements:["Private ISBN, title and borrower fields","Constructor validation","borrow(memberId) must prevent double borrowing","returnBook(memberId) must reject the wrong member","Expose isAvailable(), not a public setter"], starter:`public final class LibraryBook {\n  // fields, constructor and behavior\n}`, hint:"Represent available state with a null/Optional borrower, but never accept a blank member ID.", expected:"A second borrow attempt throws a meaningful domain exception."},
    quiz:{ question:"Which design best protects a bank account invariant?", options:["Public balance field","setBalance called from every screen","Private balance changed through deposit/withdraw methods","A global balance variable"], answer:2, explanation:"Behavioral methods centralize validation and prevent arbitrary invalid changes."}},
  { id:3, phase:"Object Builder Gate", rank:"D", title:"Interfaces, lambdas and SOLID boundaries", objective:"Create replaceable components and pass behavior safely using Java 17 functional programming.", duration:"65 min", xp:340,
    lesson:{ why:"Systems become testable and adaptable when business code depends on contracts rather than vendor details, while lambdas let small behaviors remain composable.", explanation:"An interface expresses a capability. A functional interface has one abstract method and can be implemented with a lambda or method reference. Predicate, Function, Consumer and Supplier cover common behavior shapes. Dependency inversion means policy depends on an abstraction while infrastructure implements it. Use default methods cautiously and create boundaries only when alternatives, tests or independently changing infrastructure justify them.", keyPoints:["Interfaces describe roles, not copies of implementations","A lambda implements a functional interface; it is not a magic anonymous method","Captured local variables must be final or effectively final","Constructor injection makes required dependencies visible","Liskov substitution: implementations must honor the contract"], whenToUse:["Payment, messaging, persistence and clock boundaries","Reusable validation and transformation rules","Swapping production integrations for test fakes","Keeping domain logic independent of frameworks"], code:`@FunctionalInterface\ninterface Rule<T> { boolean test(T value); }\n\nRule<Order> hasLines = order -> !order.lines().isEmpty();\nPredicate<Order> payable = Order::isPayable;\n\nfinal class Checkout {\n  private final PaymentGateway payments;\n  Checkout(PaymentGateway payments) { this.payments = payments; }\n}` , notes:["Do not create IThing/ThingImpl pairs without a real boundary","Prefer a named method when a lambda becomes difficult to explain","Dependencies should not be fetched from global service locators","Keep contracts small and cohesive"]},
    quest:{ brief:"Create an OrderCheckout service that can use card or wallet payment implementations.", requirements:["Define PaymentGateway contract","Inject it through the constructor","Reject empty carts before calling the gateway","Return a receipt without exposing gateway internals","Write a FakePaymentGateway for tests"], starter:`interface PaymentGateway { PaymentResult charge(Money amount); }\nfinal class OrderCheckout { /* inject and implement */ }`, hint:"The checkout owns business sequence; the gateway only owns external payment interaction.", expected:"A unit test can assert the charged amount without network access."},
    quiz:{ question:"When is an interface most valuable?", options:["For every class automatically","At a boundary with multiple implementations or isolated testing needs","Only for getters","To avoid constructors"], answer:1, explanation:"Interfaces earn their cost when they decouple a meaningful boundary."}},
  { id:4, phase:"Data & Reliability Gate", rank:"C", title:"Collections, generics and stream pipelines", objective:"Choose correct data structures and transform data clearly and efficiently.", duration:"60 min", xp:420,
    lesson:{ why:"Most business software is data retrieval and transformation. The wrong collection causes duplicates, slow lookups or unclear intent.", explanation:"List preserves order and permits duplicates, Set enforces uniqueness, and Map associates unique keys with values. Generics provide compile-time type safety. Streams describe transformations; use them for readable filter/map/reduce pipelines, not for stateful side effects. Know the data size and access pattern before optimizing.", keyPoints:["ArrayList is the default list; HashSet for uniqueness; HashMap for key lookup","Objects used as set elements or map keys need stable equals/hashCode","Prefer immutable results at boundaries","Streams should be side-effect free and understandable"], whenToUse:["Grouping orders by customer","Deduplicating identifiers","Building indexes for frequent lookup","Summarizing transaction data"], code:`Map<String, BigDecimal> spendByCustomer = orders.stream()\n  .filter(Order::isPaid)\n  .collect(Collectors.groupingBy(\n      Order::customerId,\n      Collectors.reducing(BigDecimal.ZERO, Order::total, BigDecimal::add)));` , notes:["Do not modify a collection while iterating unless using the iterator contract","parallelStream is not an automatic speed button","Measure before replacing readable loops with clever pipelines"]},
    quest:{ brief:"Produce an inventory alert report from a list of products and warehouse stock entries.", requirements:["Merge duplicate product entries by SKU","Keep only items below reorder level","Sort by shortage severity then SKU","Return an immutable list of alert records","Handle an empty input"], starter:`record Stock(String sku, int available, int reorderAt) {}\nrecord Alert(String sku, int shortage) {}\nstatic List<Alert> alerts(List<Stock> stock) { /* ... */ }`, hint:"Group by SKU first, then map each group to total availability and required reorder quantity.", expected:"Duplicate SKU rows result in one alert using their summed availability."},
    quiz:{ question:"Which collection is the natural choice for fast lookup by unique SKU?", options:["List<Product>","Map<String, Product>","Queue<Product>","Stack<Product>"], answer:1, explanation:"A map models the key-to-value relationship and provides direct lookup."}},
  { id:5, phase:"Data & Reliability Gate", rank:"C", title:"Exceptions, validation and reliable APIs", objective:"Represent failures intentionally and preserve useful diagnostic context.", duration:"50 min", xp:420,
    lesson:{ why:"Silent failures and vague exceptions turn small defects into long production incidents.", explanation:"Use exceptions for exceptional failure, not normal branching. Validate at system boundaries, preserve the original cause when translating infrastructure errors, and create a small domain exception vocabulary. Checked exceptions force handling but can clutter layers; unchecked exceptions suit programming errors and domain failures handled centrally.", keyPoints:["Never catch Exception and continue silently","Messages should say what failed without leaking secrets","Translate low-level exceptions at architectural boundaries","Use try-with-resources for AutoCloseable resources"], whenToUse:["Input and API validation","Converting database/client errors into service-level failures","Centralized error handling and audit logging"], code:`try {\n  return repository.find(id).orElseThrow(() -> new OrderNotFound(id));\n} catch (DatabaseException ex) {\n  throw new OrderLookupFailed(id, ex); // preserve cause\n}` , notes:["Do not use null as an undocumented failure signal","Log once at the boundary that owns handling","A retry needs limits, backoff and an idempotent operation"]},
    quest:{ brief:"Build a registration validator that returns all user-correctable issues but throws on infrastructure failure.", requirements:["Validate email, age and password","Return every validation issue together","Do not throw for ordinary invalid form input","Translate repository failure while preserving cause","Never log the password"], starter:`record Registration(String email, int age, String password) {}\nrecord ValidationResult(List<String> errors) {}`, hint:"Separate pure validation from the repository uniqueness check.", expected:"An invalid email and weak password returns two errors in one response."},
    quiz:{ question:"What should happen when translating a database exception?", options:["Discard it","Preserve it as the cause of a meaningful higher-level exception","Return null","Log the password"], answer:1, explanation:"Preserving the cause keeps the diagnostic chain while exposing an appropriate abstraction."}},
  { id:6, phase:"Concurrency Gate", rank:"B", title:"Java 17 multithreading war camp", objective:"Master threads, memory visibility, synchronization, executors, futures and failure diagnosis without races, deadlocks or resource leaks.", duration:"3–4 hrs", xp:760,
    lesson:{ why:"Concurrency defects are timing-dependent, destructive and notoriously difficult to reproduce. This is a full campaign, not a checkbox lesson.", explanation:"A thread is a scheduled execution path. Java's memory model defines when writes become visible across threads. Prefer immutable data and confinement; when state must be shared, deliberately select synchronized blocks, locks, atomics or concurrent collections. ExecutorService controls task capacity and lifecycle, while Future and CompletableFuture compose results. Every concurrent design also needs timeouts, cancellation, failure policy, shutdown and diagnostic evidence.", keyPoints:["Separate concurrency from parallelism","Atomicity, visibility and ordering are different guarantees","volatile does not make a multi-step workflow atomic","Use deterministic lock ordering to prevent deadlock","Size pools differently for CPU and blocking I/O","Shut down executors and propagate cancellation"], whenToUse:["Calling independent downstream services concurrently","Background processing with bounded capacity","Protecting shared inventory/account state","Diagnosing frozen or starved production services"], code:`ExecutorService executor = Executors.newFixedThreadPool(2);\ntry {\n  Future<Profile> profile = executor.submit(() -> profileClient.load(id));\n  Future<List<Order>> orders = executor.submit(() -> orderClient.load(id));\n  return new Dashboard(\n      profile.get(800, TimeUnit.MILLISECONDS),\n      orders.get(800, TimeUnit.MILLISECONDS));\n} finally {\n  executor.shutdown();\n}` , notes:["LevelCraft targets Java 17: virtual threads and structured concurrency are intentionally excluded","Never use sleep as a coordination strategy","An unbounded queue can hide overload until memory is exhausted","Concurrency tests should assert outcomes repeatedly and use coordination primitives"]},
    quest:{ brief:"Build a price aggregator that queries three suppliers concurrently and returns the cheapest valid result.", requirements:["Use an executor or CompletableFuture","Apply a timeout per supplier","Ignore individual supplier failure but fail if all fail","Do not leak executor threads","Make the returned result immutable"], starter:`record Quote(String supplier, BigDecimal price) {}\nQuote cheapest(List<Supplier> suppliers, String sku) { /* ... */ }`, hint:"Map suppliers to futures, handle failure per future, then choose min from successful results.", expected:"One slow and one failed supplier cannot block a valid fast quote indefinitely."},
    quiz:{ question:"What is usually the safest strategy for shared state?", options:["More global variables","Immutable data or thread confinement","Sleep statements","An unbounded thread pool"], answer:1, explanation:"Eliminating shared mutation removes entire classes of concurrency defects."}},
  { id:7, phase:"Quality Gate", rank:"B", title:"Unit tests, integration tests and refactoring", objective:"Use tests as executable evidence, then improve structure without changing behavior.", duration:"65 min", xp:560,
    lesson:{ why:"A passing application today is not evidence it will survive tomorrow's change. Focused tests create a safe change boundary.", explanation:"Unit tests isolate deterministic business behavior; integration tests verify boundaries such as database mappings. Structure each test as arrange, act, assert. Test observable behavior and edge cases instead of private methods. Refactoring changes internal design while preserving external behavior.", keyPoints:["One test should explain one behavior","Use parameterized tests for rule matrices","Avoid mocking value objects and simple data","A flaky test is a defect, not background noise"], whenToUse:["Protecting calculations and validation rules","Verifying repository and serialization mappings","Safely decomposing legacy code"], code:`@ParameterizedTest\n@CsvSource({"0,0", "100,18", "250,45"})\nvoid calculatesTax(String subtotal, String expected) {\n  assertEquals(new BigDecimal(expected), tax(new BigDecimal(subtotal)));\n}` , notes:["Coverage is a clue, not a quality score","Tests should not depend on execution order","Use a fake when behavior matters; mocks when an interaction is the contract"]},
    quest:{ brief:"Test-drive a progressive shipping-fee calculator, then refactor duplicated branches.", requirements:["Cover free-shipping threshold","Cover boundary values exactly","Reject negative totals","Use a parameterized test","Keep calculation independent of I/O"], starter:`BigDecimal shippingFor(BigDecimal orderTotal, Zone zone) {\n  throw new UnsupportedOperationException();\n}`, hint:"Write the boundary tests before implementation: just below, equal to and above the threshold.", expected:"All rule boundaries are explicit and a later tariff change touches one focused method."},
    quiz:{ question:"Which is the best unit-test target?", options:["A private helper's exact implementation","Observable behavior at rule boundaries","The Java compiler","A production database"], answer:1, explanation:"Behavior-focused tests remain valuable through refactoring."}},
  { id:8, phase:"Enterprise Gate", rank:"A", title:"Architecture, persistence and transaction boundaries", objective:"Design a layered application where domain policy survives infrastructure change.", duration:"80 min", xp:720,
    lesson:{ why:"Enterprise systems fail when transport, database and business rules become one inseparable blob.", explanation:"Organize dependencies inward: delivery adapters call application use cases; use cases coordinate domain behavior through ports; infrastructure implements persistence and external clients. A transaction should cover one consistency boundary. Do not hold database transactions open across slow network calls. Use idempotency when commands may be retried.", keyPoints:["Domain code should not depend on controllers or ORM annotations by default","Repositories express domain retrieval needs","Define transaction boundaries around a business operation","Use an outbox/event pattern when database change and message publication must agree"], whenToUse:["Order placement and payment workflows","Applications with multiple delivery mechanisms","Systems expected to change databases or integrations"], code:`final class PlaceOrder {\n  private final OrderRepository orders;\n  private final UnitOfWork tx;\n  Receipt handle(PlaceOrderCommand cmd) {\n    return tx.inTransaction(() -> {\n      Order order = Order.place(cmd.customer(), cmd.lines());\n      orders.save(order);\n      return Receipt.from(order);\n    });\n  }\n}` , notes:["Layers are dependency rules, not just folders","Do not expose ORM entities directly as API contracts","Distributed transactions are rarely the first choice"]},
    quest:{ brief:"Design and implement the core of an idempotent order-placement use case.", requirements:["Command includes an idempotency key","Duplicate key returns the original result","Domain validates non-empty lines and positive quantities","Repository is a port","Document transaction and event-publication strategy"], starter:`record PlaceOrderCommand(String requestId, String customerId, List<Line> lines) {}\ninterface OrderRepository { /* retrieval + save */ }`, hint:"Store the request ID with the order inside the same transaction.", expected:"Submitting the same request twice creates exactly one order and returns the same order ID."},
    quiz:{ question:"Why avoid network calls inside a database transaction?", options:["Java forbids it","They keep locks/resources open during unpredictable latency","HTTP is always faster","Repositories cannot call methods"], answer:1, explanation:"Long external latency expands contention and failure windows."}},
  { id:9, phase:"Expert Ascension", rank:"S", title:"Java 17 production capstone", objective:"Choose a domain and combine design, testing, multithreading and operability into a production-shaped system core.", duration:"5–8 hrs", xp:1500,
    lesson:{ why:"Expertise is integration: making reasonable trade-offs when reliability, change and delivery constraints collide.", explanation:"Choose e-commerce, library management, financial accounts, stock trading or student registration. Build explicit domain rules, application use cases, infrastructure ports, idempotency, failure translation, tests and operational evidence. Your domain changes; the engineering standard does not.", keyPoints:["Write a one-page architecture and failure-mode plan first","Use Java 17 features deliberately, including records where they fit","Apply concurrency only where independent work or shared-state pressure exists","Emit structured, correlation-friendly logs","Measure latency, errors and saturation"], whenToUse:["Portfolio evidence","Technical interviews and design reviews","Practicing production ownership before framework integration"], code:`// Suggested dependency direction\ndomain <- application <- adapters\n// Choose package-by-feature or modules, then defend it.\n// Java target: 17`, notes:["A smaller complete system beats a huge unfinished one","Explain rejected alternatives","Include a runbook: symptoms, checks, mitigation and rollback"]},
    quest:{ brief:"Choose and defend one production-shaped Java 17 capstone domain.", requirements:["Explicit domain invariants and use cases","At least one justified interface boundary","Records, lambdas or streams used where they improve the model","A meaningful concurrency problem solved and tested","Unit and integration test strategy","Structured logs plus operational runbook","README and two architecture decisions"], starter:`Begin with domain language, quality attributes and one vertical slice. Add infrastructure only after the core behavior is tested.`, hint:"Choose the domain you care about; keep the first slice narrow enough to finish and defend.", expected:"A reviewer can run tests, understand trade-offs, trigger a controlled failure and assess the chosen concurrency strategy."},
    quiz:{ question:"What makes this capstone enterprise-ready?", options:["Number of classes","Framework annotations","Testable behavior plus documented reliability and operational decisions","A colorful README"], answer:2, explanation:"Production readiness is demonstrated through behavior, evidence and operability."}},
];

export const springMissions: LearningMission[] = [
  { id:0, phase:"Spring Core Gate", rank:"E", title:"IoC, all DI styles and the ApplicationContext", objective:"Understand what Spring creates and compare constructor, setter and field injection before choosing deliberately.", duration:"75 min", xp:260,
    lesson:{ why:"Without the container mental model, annotations feel magical; without comparing injection styles, constructor injection becomes another rule memorised without understanding.", explanation:"Inversion of Control moves construction and wiring of selected application objects to the Spring container. ApplicationContext stores bean definitions, creates eligible beans and resolves dependencies. A repository in this lesson is simply an object that stores and retrieves students; no database or Spring Data knowledge is required yet. Constructor injection makes required collaborators explicit and supports immutability. Setter injection can represent a genuinely optional collaborator. Field injection works, but hides dependencies and complicates plain unit tests.", keyPoints:["A bean is an object managed by the container—not every object should be one","A repository begins here as a plain storage contract—not Spring Data JPA","Constructor injection is the default for required dependencies","Setter injection can model a truly optional dependency with a safe default","Field injection works inside Spring but hides the construction contract","@Qualifier and @Primary resolve multiple matching beans"], whenToUse:["Wiring application services to repositories and API clients","Keeping business code testable without starting Spring","Selecting between multiple implementations","Centralizing configuration-dependent construction"], code:`// A domain value. It is not a Spring bean.\nrecord Student(String id, String name) {}\n\n// A small storage contract; no database knowledge is required.\ninterface StudentRepository {\n  void save(Student student);\n  Optional<Student> findById(String id);\n}\n\n// Beginner-friendly implementation: no Spring Data and no database.\nfinal class InMemoryStudentRepository implements StudentRepository {\n  private final Map<String, Student> students = new HashMap<>();\n\n  public void save(Student student) { students.put(student.id(), student); }\n  public Optional<Student> findById(String id) {\n    return Optional.ofNullable(students.get(id));\n  }\n}\n\n// Plain Java constructor injection. Spring is not involved yet.\nfinal class StudentService {\n  private final StudentRepository repository;\n\n  StudentService(StudentRepository repository) {\n    this.repository = Objects.requireNonNull(repository);\n  }\n\n  void register(String id, String name) {\n    repository.save(new Student(id, name));\n  }\n}\n\n// Manual wiring: you create and connect the objects.\nvar repository = new InMemoryStudentRepository();\nvar service = new StudentService(repository);\nservice.register("S-001", "Mira");` , notes:["Understand manual construction before adding Spring annotations","Implement the three injection styles in separate comparison classes","Do not make DTOs, entities and value objects beans by default","Singleton means one instance per context, not thread-local state","Circular dependencies usually reveal a design problem"]},
    quest:{ brief:"After the guided StudentService comparison, implement a notification service three ways and select the production design.", requirements:["Define Message and NotificationChannel before adding Spring annotations","Create EmailChannel and SmsChannel implementations","Build separate constructor-, setter-, and field-injected service versions","Classify each dependency as required or optional","Resolve multiple channel beans intentionally","Unit-test the constructor version without Spring","Document why the rejected styles were not selected"], starter:`record Message(String recipient, String body) {}\n\ninterface NotificationChannel {\n  void send(Message message);\n}\n\nfinal class EmailChannel implements NotificationChannel {\n  public void send(Message message) {\n    System.out.println("EMAIL -> " + message.recipient());\n  }\n}\n\n// Start with plain Java constructor injection.\nfinal class NotificationService {\n  private final NotificationChannel channel;\n\n  NotificationService(NotificationChannel channel) {\n    this.channel = channel;\n  }\n\n  void notify(Message message) { channel.send(message); }\n}\n\n// Only after this runs, create separate Spring-managed comparisons.`, hint:"Do not mix all three styles in one class. Make three small versions so construction and test setup can be compared side by side.", expected:"The learner can create, run and unit-test each design, then explain why constructor injection best represents the required channel."},
    quiz:{ question:"What is the strongest reason to prefer constructor injection?", options:["Fewer characters","Dependencies become explicit and testable","It creates global state","It avoids interfaces"], answer:1, explanation:"Constructor injection makes invalid partially constructed objects difficult to create."}},
  { id:1, phase:"Spring Boot Gate", rank:"D", title:"Boot auto-configuration, starters and external configuration", objective:"Know what Spring Boot adds and control it without cargo-cult annotations.", duration:"55 min", xp:280,
    lesson:{ why:"Boot accelerates setup, but production systems require knowing how defaults are selected and overridden.", explanation:"Spring Boot combines opinionated starters, conditional auto-configuration and an executable application model. @SpringBootApplication includes configuration, component scanning and auto-configuration. Auto-configurations activate when classes, properties and missing beans satisfy conditions. Use type-safe @ConfigurationProperties for grouped settings and validate them at startup.", keyPoints:["Starters align compatible dependencies","Auto-configuration backs off when you provide your own bean","Keep secrets out of application.yml and source control","Use profiles sparingly; prefer environment configuration"], whenToUse:["Creating deployable services quickly","Changing behavior by environment","Replacing a default client, serializer or data source deliberately"], code:`@ConfigurationProperties("payments")\n@Validated\nrecord PaymentProperties(\n  @NotBlank String baseUrl,\n  @DurationMin(seconds=1) Duration timeout) {}\n\n@SpringBootApplication\n@ConfigurationPropertiesScan\nclass OrdersApplication {}` , notes:["Do not scatter @Value strings across the codebase","Inspect condition reports when auto-configuration surprises you","Fail startup when required configuration is absent"]},
    quest:{ brief:"Create validated configuration for a document-storage client.", requirements:["Prefix storage","Endpoint, bucket and timeout fields","Validation for blank/invalid values","Separate local and production values without committing secrets","Expose one client bean built from the properties"], starter:`@ConfigurationProperties("storage")\nrecord StorageProperties(/* fields */) {}`, hint:"Use jakarta validation annotations and @ConfigurationPropertiesScan.", expected:"The application refuses to start with a blank bucket and reports the exact property."},
    quiz:{ question:"When does Boot auto-configuration usually back off?", options:["Never","When its conditions fail or the application provides the relevant bean","Only on Windows","After the first request"], answer:1, explanation:"Boot uses conditional configuration, including missing-bean conditions."}},
  { id:2, phase:"Web API Gate", rank:"C", title:"REST controllers, DTOs and validation contracts", objective:"Design an API boundary that is stable, validated and independent from persistence entities.", duration:"70 min", xp:420,
    lesson:{ why:"APIs become long-lived contracts. Leaking entities or inconsistent errors couples consumers to internal accidents.", explanation:"Controllers translate HTTP into application commands and responses. DTOs define the external contract. Bean Validation checks structural input; application/domain services enforce business rules. Use correct status codes, location headers for creation, and a consistent problem response. Keep controllers thin.", keyPoints:["Do not return JPA entities directly","Use @Valid on request DTOs","Separate malformed input, business conflict and missing resource","Version contracts deliberately, not by copying entire controllers"], whenToUse:["Public and internal JSON APIs","Protecting domain models from transport changes","Providing actionable validation errors"], code:`record CreateOrderRequest(@NotEmpty List<LineRequest> lines) {}\nrecord OrderResponse(UUID id, String status) {}\n\n@RestController\n@RequestMapping("/orders")\nclass OrderController {\n  @PostMapping ResponseEntity<OrderResponse> create(\n      @Valid @RequestBody CreateOrderRequest request) { /* map + call */ }\n}` , notes:["POST create commonly returns 201","PUT should be idempotent; PATCH semantics must be explicit","Never expose stack traces to clients"]},
    quest:{ brief:"Implement a student-registration endpoint with a clean request, response and error contract.", requirements:["Validate name, email and birth date","Return 201 and Location header","Reject duplicate email as 409","Return field-level validation errors","Map request DTO to application command"], starter:`record RegisterStudentRequest(/* validated fields */) {}\n@PostMapping("/students")\nResponseEntity<StudentResponse> register(...) {}`, hint:"Use @RestControllerAdvice for consistent exceptions; do not catch everything in the controller.", expected:"Invalid input returns a stable problem JSON; valid registration never exposes the entity."},
    quiz:{ question:"Where should the rule 'email must be unique' live?", options:["Only in JavaScript","Application/domain logic backed by a database constraint","In the response DTO","Nowhere"], answer:1, explanation:"It is a business invariant and must also be enforced at the persistence boundary against races."}},
  { id:3, phase:"Web API Gate", rank:"C", title:"Global errors, logging and API observability", objective:"Make failures consistent for clients and diagnosable for operators.", duration:"55 min", xp:420,
    lesson:{ why:"A correct success path is only half an API. Production quality is revealed by its failure behavior.", explanation:"Use @RestControllerAdvice to map known exceptions into a consistent problem schema. Include a safe error code and correlation ID. Log structured context at the handling boundary, not in every layer. Metrics should show request rate, failures and latency; traces connect calls across services.", keyPoints:["Map domain failures intentionally","Do not return exception messages blindly","Avoid duplicate logging at every rethrow","Never log tokens, passwords or sensitive payloads"], whenToUse:["Uniform errors across controllers","Investigating multi-service incidents","Defining alertable service-level indicators"], code:`@ExceptionHandler(OrderNotFound.class)\nResponseEntity<ProblemDetail> notFound(OrderNotFound ex) {\n  var problem = ProblemDetail.forStatus(404);\n  problem.setTitle("Order not found");\n  problem.setProperty("code", "ORDER_NOT_FOUND");\n  return ResponseEntity.status(404).body(problem);\n}` , notes:["4xx errors are not automatically server incidents","Use correlation IDs consistently across logs and responses","Metrics labels must have bounded cardinality"]},
    quest:{ brief:"Add production-grade failure handling to the student API.", requirements:["Map not-found, duplicate and validation failures","Use ProblemDetail with stable codes","Include correlation ID","Log unexpected 5xx once with cause","Define request, error and latency metrics"], starter:`@RestControllerAdvice\nclass ApiExceptionHandler { /* handlers */ }`, hint:"Keep validation-field extraction in a small helper and test the JSON shape.", expected:"Every known failure produces the documented status and schema; unexpected errors hide internals."},
    quiz:{ question:"Why avoid customer ID as a metric label?", options:["It is too readable","It creates unbounded high cardinality","Metrics cannot contain text","It changes HTTP status"], answer:1, explanation:"Unbounded label values make metrics expensive and difficult to aggregate."}},
  { id:4, phase:"Persistence Gate", rank:"B", title:"Spring Data JPA entities, repositories and transactions", objective:"Persist business state without hiding SQL costs or corrupting transaction boundaries.", duration:"80 min", xp:560,
    lesson:{ why:"JPA reduces mapping code but can create N+1 queries, accidental writes and leaky persistence models.", explanation:"An entity has persistence identity and lifecycle. Repositories express required queries. @Transactional defines a unit of work; changes to managed entities are flushed at commit. Lazy relationships avoid loading everything but fail outside the persistence context and can cause N+1 query storms. Prefer focused queries/projections for read models.", keyPoints:["Place transactions on application service methods","Keep transactions short; do not call slow remote services inside","Use database constraints for true uniqueness","Inspect generated SQL and query plans"], whenToUse:["Transactional relational workflows","Aggregate persistence","Paginated and filtered application queries"], code:`@Transactional\npublic StudentId register(RegisterStudent cmd) {\n  if (students.existsByEmail(cmd.email())) throw new DuplicateEmail();\n  var student = Student.register(cmd.name(), cmd.email());\n  return students.save(student).id();\n}` , notes:["exists-then-insert still needs a unique database constraint","Do not use CascadeType.ALL blindly","Page large result sets; never load an unbounded table"]},
    quest:{ brief:"Persist students and course enrolments with correct ownership and queries.", requirements:["Unique email constraint","Explicit relationship owner","Transactional enrolment use case","Paginated student search projection","Integration test for duplicate and rollback behavior"], starter:`@Entity class Student { /* id, email, enrolments */ }\ninterface StudentRepository extends JpaRepository<Student, UUID> {}`, hint:"Model the aggregate boundary before adding bidirectional relationships.", expected:"Duplicate email is impossible under concurrent requests, and list endpoints do not trigger N+1 queries."},
    quiz:{ question:"Why is an application-level existsByEmail check insufficient alone?", options:["It is too fast","Concurrent requests can both pass before insert","Repositories cannot return boolean","Email has no type"], answer:1, explanation:"Only a database uniqueness constraint closes the race reliably."}},
  { id:5, phase:"Security & Quality Gate", rank:"B", title:"Spring Security authentication and authorization", objective:"Protect resources with explicit, testable rules and safe defaults.", duration:"80 min", xp:620,
    lesson:{ why:"A login page is not security. Enterprise services must authenticate identity, authorize every protected action and defend common attack paths.", explanation:"Spring Security applies a filter chain before controllers. Authentication establishes identity; authorization decides permission. Configure request rules explicitly and use method security for domain-sensitive operations. Store passwords with a modern one-way encoder. For stateless APIs validate tokens; for browser sessions address CSRF intentionally.", keyPoints:["Deny by default and permit only intentional public endpoints","Authorization must be server-side","Passwords are hashed, never encrypted or logged","Test both allowed and forbidden paths"], whenToUse:["Role- and ownership-based API rules","OAuth2 resource servers","Protecting administrative and user-owned data"], code:`@Bean\nSecurityFilterChain api(HttpSecurity http) throws Exception {\n  return http\n    .authorizeHttpRequests(a -> a\n      .requestMatchers("/actuator/health").permitAll()\n      .requestMatchers("/admin/**").hasRole("ADMIN")\n      .anyRequest().authenticated())\n    .oauth2ResourceServer(o -> o.jwt())\n    .build();\n}` , notes:["CORS is not authorization","Do not disable CSRF without understanding the client credential model","Avoid exposing whether a user account exists"]},
    quest:{ brief:"Secure the student API for STUDENT and ADMIN roles with ownership checks.", requirements:["Public health endpoint only","Students read only their own profile","Admins can list all students","Return 401 vs 403 correctly","Add security tests for every rule"], starter:`@EnableMethodSecurity\n@Configuration class SecurityConfiguration { /* chain */ }`, hint:"Use a small authorization service or @PreAuthorize expression that compares authenticated subject to resource owner.", expected:"Changing the URL or request body cannot bypass ownership authorization."},
    quiz:{ question:"What is the difference between 401 and 403?", options:["They are identical","401 means authentication is missing/invalid; 403 means identity lacks permission","403 means success","401 is database failure"], answer:1, explanation:"Authentication and authorization failures are distinct contracts."}},
  { id:6, phase:"Security & Quality Gate", rank:"B", title:"Spring testing from unit to container", objective:"Build a fast test portfolio that proves rules, web contracts and persistence behavior.", duration:"70 min", xp:580,
    lesson:{ why:"Starting the whole application for every test is slow; mocking everything misses broken wiring and mappings.", explanation:"Use plain JUnit for domain/services, @WebMvcTest for controller and serialization slices, @DataJpaTest for repository mappings, and @SpringBootTest sparingly for critical full flows. Testcontainers provides real infrastructure behavior. Mock external boundaries, not the class under test.", keyPoints:["Choose the smallest test scope that proves the risk","Use MockMvc/WebTestClient for HTTP contracts","Rollback test data or isolate it","Keep tests deterministic and parallel-safe"], whenToUse:["Validation and error contract tests","Custom repository query verification","End-to-end application smoke tests"], code:`@WebMvcTest(StudentController.class)\nclass StudentControllerTest {\n  @Autowired MockMvc mvc;\n  @MockBean RegisterStudent register;\n  @Test void rejectsInvalidEmail() throws Exception {\n    mvc.perform(post("/students").contentType(APPLICATION_JSON)\n      .content("{\\"email\\":\\"bad\\"}"))\n      .andExpect(status().isBadRequest());\n  }\n}` , notes:["Do not overuse @SpringBootTest","A test passing against H2 may not prove PostgreSQL behavior","Assert response contracts, not incidental JSON ordering"]},
    quest:{ brief:"Create a testing pyramid for the student registration feature.", requirements:["Unit tests for domain rules","Web slice tests for success and validation","JPA test for unique constraint and query","One full smoke flow with real database container","No test depends on execution order"], starter:`class StudentRegistrationTest { /* unit */ }\n@WebMvcTest(...) class StudentApiTest { /* contract */ }`, hint:"List the risk each test protects before writing it.", expected:"Most tests run without Spring; focused integration tests catch mapping and wiring failures."},
    quiz:{ question:"When should @SpringBootTest be preferred?", options:["For every getter","For a small number of critical full-context flows","To test a pure calculation","Never"], answer:1, explanation:"Full-context tests are valuable but slower and broader than most behavior needs."}},
  { id:7, phase:"Distributed Systems Gate", rank:"A", title:"HTTP clients, resilience and idempotency", objective:"Integrate downstream services without turning their failures into cascading outages.", duration:"85 min", xp:720,
    lesson:{ why:"Every network call can be slow, fail or produce an uncertain outcome. Resilience is explicit product behavior.", explanation:"Configure connection and response timeouts. Retry only transient, safe operations with bounded attempts and backoff. Circuit breakers stop repeated calls to a failing dependency. Bulkheads protect capacity. Idempotency keys make retried commands safe. Define fallback only when degraded data is acceptable.", keyPoints:["Timeout every remote call","Do not retry validation errors or non-idempotent operations blindly","Budget retries within the caller's deadline","Measure dependency latency, errors and circuit state"], whenToUse:["Payment, inventory and identity clients","Protecting thread/connection pools","Recovering from transient infrastructure faults"], code:`@Bean RestClient paymentClient(PaymentProperties p) {\n  var factory = new JdkClientHttpRequestFactory();\n  factory.setReadTimeout(p.timeout());\n  return RestClient.builder().baseUrl(p.baseUrl())\n      .requestFactory(factory).build();\n}` , notes:["Retries multiply load during outages","A circuit breaker is not a substitute for timeout","Trace IDs should flow to downstream calls"]},
    quest:{ brief:"Integrate an inventory reservation API safely into order placement.", requirements:["Connection/read timeout","Retry only transient idempotent reservation using request key","Circuit breaker and bounded fallback decision","Map remote errors into application failures","Tests for timeout, retry and duplicate request"], starter:`interface InventoryClient { Reservation reserve(String requestId, List<Item> items); }`, hint:"Define the failure policy in plain language before configuring a library.", expected:"A repeated request cannot reserve stock twice, and dependency outage does not exhaust service capacity."},
    quiz:{ question:"What is the biggest risk of indiscriminate retries?", options:["Cleaner code","Amplifying load and repeating non-idempotent effects","Lower latency","Fewer logs"], answer:1, explanation:"Retries can worsen an outage and duplicate business actions."}},
  { id:8, phase:"Production Gate", rank:"A", title:"Actuator, metrics, configuration and deployment", objective:"Make a service observable, configurable and safe to operate.", duration:"75 min", xp:720,
    lesson:{ why:"If operators cannot tell whether a service is healthy or why it is failing, it is not production-ready.", explanation:"Actuator exposes operational endpoints. Separate liveness (process can run) from readiness (can serve traffic). Export Micrometer metrics for request rate, errors, latency and business outcomes. Use structured logging, externalized configuration and graceful shutdown. Container images should be reproducible and run as non-root.", keyPoints:["Expose only required actuator endpoints","Health details may contain sensitive information","Alerts should represent user impact","Deployment needs rollback and database migration strategy"], whenToUse:["Kubernetes readiness/liveness probes","Dashboards and alerting","Safe configuration changes and incident response"], code:`management:\n  endpoints.web.exposure.include: health,info,prometheus\n  endpoint.health.probes.enabled: true\nserver.shutdown: graceful\nspring.lifecycle.timeout-per-shutdown-phase: 20s` , notes:["Do not alert on every log line","A readiness check should not depend on every optional integration","Use immutable image tags or digests"]},
    quest:{ brief:"Prepare the student service for a controlled production deployment.", requirements:["Liveness and readiness probes","Custom registration success/failure metrics","Structured logs with correlation ID","Container runs non-root","Migration, rollback and incident runbook","Dashboard for rate, errors and p95 latency"], starter:`Create an operations/ folder with dashboard notes, runbook and deployment checklist.`, hint:"For each alert, write the user impact and first three diagnostic steps.", expected:"An operator can detect failure, identify the affected dependency and safely roll back."},
    quiz:{ question:"What should readiness communicate?", options:["The process exists","The instance can currently receive traffic","All historical jobs succeeded","The code compiled"], answer:1, explanation:"Readiness controls whether the platform should route requests to the instance."}},
  { id:9, phase:"Expert Ascension", rank:"S", title:"Spring Boot enterprise capstone", objective:"Choose a domain and deliver, test and defend a secure production-shaped service from API to operations.", duration:"8–14 hrs", xp:1800,
    lesson:{ why:"Enterprise readiness is demonstrated by an operable system and defensible decisions, not by annotation count.", explanation:"Choose e-commerce, library management, financial accounts, stock trading or student registration. Build a modular monolith first: independent domain policy, versioned HTTP contracts, PostgreSQL persistence, security, one resilient integration and operational evidence. Record architecture decisions and rejected alternatives.", keyPoints:["Start with use cases and quality attributes","Use versioned database migrations","Automate tests and quality gates in CI","Run a security and failure drill before completion","Prefer a complete modular monolith before extracting microservices"], whenToUse:["Portfolio and interview demonstration","Team onboarding reference","Practicing end-to-end delivery ownership"], code:`// Suggested feature structure\nfeature/domain\nfeature/application\nfeature/web\nfeature/persistence\nfeature/integrations\n// Enforce dependency direction`, notes:["The selected domain changes examples, not quality standards","Document threat model and data ownership","Include sample requests but never real secrets"]},
    quest:{ brief:"Choose, build and deploy one Spring Boot enterprise capstone.", requirements:["Versioned REST contracts and validation","PostgreSQL schema with migrations and constraints","Role and ownership security","Resilient external integration","Unit, web-slice, repository and smoke tests","Container, metrics, dashboard and runbook","Architecture diagram plus two ADRs","Controlled failure drill"], starter:`Create a Java 17 Spring Boot project with Web, Validation, Data JPA, Security, Actuator and PostgreSQL. Deliver one complete vertical slice before expanding.`, hint:"Domain ambition is welcome; unfinished infrastructure is not. Finish one production-shaped slice first.", expected:"A reviewer can deploy it, exercise documented APIs, observe metrics, trigger a controlled failure and recover using the runbook."},
    quiz:{ question:"What is the strongest capstone completion evidence?", options:["It starts on a laptop","A deployable service with tested behavior, security, telemetry and recovery documentation","It has many dependencies","It uses microservices"], answer:1, explanation:"End-to-end evidence shows deployability and operational ownership."}},
];

